import * as util from "@ark/util";
import { Hkt } from "@ark/util";
import { scope } from "../scope.js";
// these are needed to create some internal types
import { genericNode, intrinsic } from "@ark/schema";
import "./ts.js";
class liftArrayHkt extends Hkt {
}
const liftArray = genericNode("element")(args => args.element.or(args.element.array()).pipe(util.liftArray), liftArrayHkt);
class mergeHkt extends Hkt {
}
const merge = genericNode(["base", intrinsic.object], ["props", intrinsic.object])(args => args.base.merge(args.props), mergeHkt);
const keywords = scope({
    key: intrinsic.key,
    nonNegativeIntegerString: intrinsic.nonNegativeIntegerString,
    liftArray,
    merge
}).export();
export const arkBuiltin = {
    keywords
};
